require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('expenses');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM expenses WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){flash('danger','Expense not found.');redirect('expenses/index.php');}if(role_name()==='Staff'&&(int)$r['requested_by']!==(int)current_user()['id']){http_response_code(403);exit('Forbidden');}
$pageTitle='Edit Expense';$activeMenu='expense-list';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['expense_date'];$dept=(int)$_POST['department_id'];$cat=(int)$_POST['category_id'];$desc=trim($_POST['description']);$amount=(float)$_POST['amount'];if(!valid_date($date)||!$dept||!$cat||$desc===''||$amount<=0)$errors[]='Please complete all required fields with valid values.';if(!$errors){db()->prepare("UPDATE expenses SET expense_date=?,department_id=?,category_id=?,description=?,amount=?,status='Pending',updated_at=NOW() WHERE id=?")->execute([$date,$dept,$cat,$desc,$amount,$id]);$a=db()->prepare("SELECT id FROM approvals WHERE request_type='expense' AND request_id=? LIMIT 1");$a->execute([$id]);$aid=$a->fetchColumn();if($aid){db()->prepare("UPDATE approvals SET current_stage='department_manager',status='Pending',remarks=NULL,updated_at=NOW() WHERE id=?")->execute([$aid]);db()->prepare("INSERT INTO approval_history(approval_id,stage,action,action_by,remarks) VALUES(?,'request','Resubmitted',?,'Expense edited and resubmitted')")->execute([$aid,current_user()['id']]);}else save_approval_request('expense',$id);log_activity('UPDATE','Expense','Edited '.$r['expense_code']);flash('success','Expense updated and resubmitted.');redirect('expenses/index.php');}}
$departments=departments();$categories=categories();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Edit Expense</h1><p><?=e($r['expense_code'])?> · Changes reset the approval workflow.</p></div><a class="btn btn-light border" href="<?=e(url('expenses/index.php'))?>">Back</a></div><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="card-panel"><div class="card-body"><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-4"><label class="form-label">Date</label><input class="form-control" type="date" name="expense_date" value="<?=e($_POST['expense_date']??$r['expense_date'])?>"></div><div class="col-md-4"><label class="form-label">Department</label><select class="form-select" name="department_id"><?php foreach($departments as $d):?><option value="<?=$d['id']?>" <?=((int)($_POST['department_id']??$r['department_id'])===(int)$d['id'])?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Category</label><select class="form-select" name="category_id"><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((int)($_POST['category_id']??$r['category_id'])===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description"><?=e($_POST['description']??$r['description'])?></textarea></div><div class="col-md-6"><label class="form-label">Amount</label><input class="form-control" type="number" step=".01" min=".01" name="amount" value="<?=e($_POST['amount']??$r['amount'])?>"></div><div class="col-12"><button class="btn btn-primary">Update & Resubmit</button></div></div></form></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
